{
  "a_sentences": [
    {
      "a_text": "L'objet de la contestation devant le Tribunal fédéral est déterminé par l'arrêt attaqué et ne peut être ni élargi ni transformé par rapport à ce qu'il était devant l'autorité précédente.",
      "b_propositions": ["P1", "P2"]
    },
    {
      "a_text": "La juridiction cantonale a constaté que la planification hospitalière vaudoise de 2012 était entrée en force, n'ayant pas été contestée auprès du Tribunal administratif fédéral.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Cette planification cantonale, incluant l'évaluation des besoins en soins et les quotas imposés aux établissements, était réputée conforme au droit et s'appliquait à tous les établissements figurant sur la liste hospitalière vaudoise.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "La répartition des rémunérations des soins hospitaliers entre les cantons et les assureurs était imposée par la loi, les cantons devant prendre en charge au moins 55 % des frais.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Un examen préjudiciel ou incident de la légalité de la planification hospitalière cantonale, en particulier des quotas, n'a pas lieu d'être en l'espèce.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "La recourante ne pouvant contester la légalité de la planification hospitalière vaudoise, elle ne saurait reprocher à l'intimé de ne pas avoir pris en charge sa part des frais hospitaliers dans la mesure où ils excéderaient les limites quantitatives prévues.",
      "b_propositions": ["P8"]
    }
  ]
}
